    async function loadMyWeekSuggestion() {
      var envelope = await tryRequest('api/v1/ai/suggestions', {
        query: { intent_code: 'my_week_plan', entity_type: 'user', limit: 20 },
        silent: true
      });
      var items = envelope && envelope.data && Array.isArray(envelope.data.items) ? envelope.data.items : [];
      items.sort(function (a, b) {
        return toTimestamp((b && (b.updated_at || b.created_at)) || '') - toTimestamp((a && (a.updated_at || a.created_at)) || '');
      });
      var selected = items.find(function (item) {
        var payload = item && item.payload && typeof item.payload === 'object' ? item.payload : {};
        return Array.isArray(payload.tasks_by_day) && payload.tasks_by_day.length > 0;
      }) || items[0] || null;
      if (selected && selected.public_id) {
        try {
          var detailEnvelope = await tryRequest('api/v1/ai/suggestions/' + encodeURIComponent(selected.public_id), { silent: true });
          if (detailEnvelope && detailEnvelope.data && detailEnvelope.data.suggestion) {
            return detailEnvelope.data.suggestion;
          }
        } catch (e) {
          // Keep lightweight item if detail loading fails.
        }
      }
      return selected;
    }

