    var sunday = new Date(monday);
    sunday.setDate(sunday.getDate() + 6);
    var weekFrom = monday.getFullYear() + '-' + String(monday.getMonth() + 1).padStart(2, '0') + '-' + String(monday.getDate()).padStart(2, '0');
    var weekTo = sunday.getFullYear() + '-' + String(sunday.getMonth() + 1).padStart(2, '0') + '-' + String(sunday.getDate()).padStart(2, '0');
    var yesterday = new Date(Date.now() - 86400000).toISOString().split('T')[0];
