  // Gantt helpers - start
  function parseGanttDate(value) {
    if (!value) return null;
    var date = new Date(value);
    return isNaN(date.getTime()) ? null : date;
  }

  function getGanttTaskStart(task) {
    if (!task) return null;
    var fields = ['start_at', 'started_at', 'planned_start_at', 'actual_start_at', 'created_at'];
    for (var i = 0; i < fields.length; i++) {
      var date = parseGanttDate(task[fields[i]]);
      if (date) return date;
    }
    return null;
  }

  function getGanttTaskEnd(task) {
    if (!task) return null;
    var fields = ['due_at', 'deadline_at', 'finish_at', 'finished_at', 'completed_at', 'end_at', 'planned_end_at'];
    for (var i = 0; i < fields.length; i++) {
      var date = parseGanttDate(task[fields[i]]);
      if (date) return date;
    }
    return null;
  }

  function normalizeGanttTask(task) {
    if (!task) return null;
    var start = getGanttTaskStart(task);
    var end = getGanttTaskEnd(task);
    var now = new Date();

    if (!start && end) {
      // If no start but has end, create short interval before end
      start = new Date(end.getTime() - 7 * 24 * 60 * 60 * 1000); // 7 days before
    } else if (start && !end) {
      // If no end but has start, create short interval after start
      end = new Date(start.getTime() + 7 * 24 * 60 * 60 * 1000); // 7 days after
    }

    var isOverdue = end && end < now && task.status_code !== 'completed' && task.status_code !== 'done';
    var isBlocked = task.status_code === 'blocked' || task.status_code === 'on_hold';

    return {
      id: task.id || '',
      title: task.title || '',
      projectId: task.project_id || '',
      projectTitle: task.project_title || task.project_name || '',
      statusCode: task.status_code || 'new',
      statusLabel: statusLabel(task.status_code) || 'Новый',
      statusKind: getGanttStatusKind(task),
      assignee: task.assignee_name || task.assigned_to || '',
      start: start,
      end: end,
      isOverdue: !!isOverdue,
      isBlocked: !!isBlocked,
      raw: task
    };
  }

  function getGanttStatusKind(task) {
    if (!task || !task.status_code) return 'active';
    var code = task.status_code;
    if (code === 'completed' || code === 'done' || code === 'closed') return 'success';
    if (code === 'blocked' || code === 'on_hold') return 'blocked';
    if (code === 'in_review' || code === 'review') return 'review';
    if (code === 'cancelled' || code === 'archived') return 'archived';
    return 'active'; // in_progress, new, etc.
  }

  function groupGanttTasksByProject(items) {
    var groups = {};
    var withoutDates = [];
    items.forEach(function (item) {
      if (!item.start && !item.end) {
        withoutDates.push(item);
        return;
      }
      var pid = item.projectId || 'no_project';
      if (!groups[pid]) {
        groups[pid] = {
          projectId: pid,
          projectTitle: item.projectTitle || 'Без проекта',
          tasks: [],
          minStart: null,
          maxEnd: null
        };
      }
      groups[pid].tasks.push(item);
      if (item.start && (!groups[pid].minStart || item.start < groups[pid].minStart)) {
        groups[pid].minStart = item.start;
      }
      if (item.end && (!groups[pid].maxEnd || item.end > groups[pid].maxEnd)) {
        groups[pid].maxEnd = item.end;
      }
    });
    return {
      groups: Object.values(groups),
      withoutDates: withoutDates
    };
  }

  function buildGanttWindow(items, zoomMode) {
    if (!items || items.length === 0) {
      var now = new Date();
      return {
        windowStart: new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000),
        windowEnd: new Date(now.getTime() + 7 * 24 * 60 * 60 * 1000),
        scale: [],
        today: null
      };
    }

    var minStart = null, maxEnd = null;
    items.forEach(function (item) {
      if (item.start && (!minStart || item.start < minStart)) minStart = item.start;
      if (item.end && (!maxEnd || item.end > maxEnd)) maxEnd = item.end;
    });

    if (!minStart || !maxEnd) {
      var fallback = new Date();
      minStart = minStart || new Date(fallback.getTime() - 7 * 24 * 60 * 60 * 1000);
      maxEnd = maxEnd || new Date(fallback.getTime() + 7 * 24 * 60 * 60 * 1000);
    }

    // Add padding
    var padding = 7 * 24 * 60 * 60 * 1000; // 7 days
    var windowStart = new Date(minStart.getTime() - padding);
    var windowEnd = new Date(maxEnd.getTime() + padding);

    var scale = [];
    var now = new Date();
    var today = null;

    if (zoomMode === 'days') {
      for (var d = new Date(windowStart); d <= windowEnd; d.setDate(d.getDate() + 1)) {
        var isWeekend = d.getDay() === 0 || d.getDay() === 6;
        var label = formatDate(d, { format: 'short' }); // Assume formatDate from helpers
        scale.push({
          date: new Date(d),
          label: label,
          isWeekend: isWeekend
        });
        if (!today && d.toDateString() === now.toDateString()) {
          today = scale.length - 1;
        }
      }
    } else if (zoomMode === 'weeks') {
      var startWeek = new Date(windowStart);
      startWeek.setDate(startWeek.getDate() - startWeek.getDay()); // Start of week
      for (var w = new Date(startWeek); w <= windowEnd; w.setDate(w.getDate() + 7)) {
        var weekEnd = new Date(w.getTime() + 6 * 24 * 60 * 60 * 1000);
        var label = formatDate(w, { format: 'short' }) + ' - ' + formatDate(weekEnd, { format: 'short' });
        scale.push({
          date: new Date(w),
          label: label,
          isWeekend: false
        });
        if (!today && w <= now && weekEnd >= now) {
          today = scale.length - 1;
        }
      }
    } else if (zoomMode === 'months') {
      var startMonth = new Date(windowStart.getFullYear(), windowStart.getMonth(), 1);
      for (var m = new Date(startMonth); m <= windowEnd; m.setMonth(m.getMonth() + 1)) {
        var label = m.toLocaleDateString('ru-RU', { month: 'long', year: 'numeric' });
        scale.push({
          date: new Date(m),
          label: label,
          isWeekend: false
        });
        if (!today && m.getMonth() === now.getMonth() && m.getFullYear() === now.getFullYear()) {
          today = scale.length - 1;
        }
      }
    }

    return {
      windowStart: windowStart,
      windowEnd: windowEnd,
      scale: scale,
      today: today
    };
  }

  // Gantt helpers - end

  function crmGanttGetCollapsedProjects() {
    if (!window.CRM) window.CRM = {};
    if (!window.CRM.ganttCollapsedProjects) {
      window.CRM.ganttCollapsedProjects = {};
    }
    return window.CRM.ganttCollapsedProjects;
  }

  function crmGanttGetKpiFilter() {
    if (!window.CRM) window.CRM = {};
    if (!window.CRM.ganttKpiFilter) {
      window.CRM.ganttKpiFilter = 'all';
    }
    return window.CRM.ganttKpiFilter;
  }

  function crmGanttSetKpiFilter(value) {
    if (!window.CRM) window.CRM = {};
    var next = value || 'all';
    window.CRM.ganttKpiFilter = next;
    var state = crmGanttEnsureState();
    state.kpiFilter = next;
  }

  function crmGanttApplyKpiFilter(items, filter) {
    if (!filter || filter === 'all') return items.slice();

    return items.filter(function (item) {
      if (filter === 'active') return item.kind !== 'success' && item.kind !== 'archived';
      if (filter === 'overdue') return !!item.isOverdue;
      if (filter === 'blocked') return !!item.isBlocked;
      if (filter === 'completed') return item.kind === 'success';
      if (filter === 'without_dates') return !item.hasDates;
      return true;
    });
  }

  function crmGanttBindKpiFilters() {
    var root = document.getElementById('ganttSummaryTiles');
    if (!root || root.dataset.ganttKpiBound === '1') return;

    root.addEventListener('click', function (event) {
      var button = event.target.closest('[data-gantt-kpi-filter]');
      if (!button) return;

      event.preventDefault();

      var next = button.getAttribute('data-gantt-kpi-filter') || 'all';
      var current = crmGanttGetKpiFilter();

      crmGanttSetKpiFilter(current === next ? 'all' : next);

      renderGanttPage().catch(function (error) {
        console.error('[GANTT] KPI filter render failed', error);
        if (typeof notify === 'function') notify('Не удалось применить фильтр диаграммы', 'error');
      });
    });

    root.dataset.ganttKpiBound = '1';
  }

  function crmGanttBindLegendStatusFilters() {
    var legendEl = document.getElementById('ganttLegend');
    if (!legendEl || legendEl.dataset.statusFilterBound === '1') return;

    legendEl.addEventListener('click', function (event) {
      var chip = event.target.closest('[data-gantt-status-filter]');
      if (!chip) return;

      event.preventDefault();

      var status = chip.getAttribute('data-gantt-status-filter');
      var ss = crmGanttEnsureState();
      ss.statusFilters = ss.statusFilters || [];
      var idx = ss.statusFilters.indexOf(status);
      if (idx === -1) { ss.statusFilters.push(status); } else { ss.statusFilters.splice(idx, 1); }

      renderGanttPage().catch(function (err) { console.error('[GANTT] status filter rerender', err); });
    });

    legendEl.dataset.statusFilterBound = '1';
  }

  // ── Gantt State ──────────────────────────────────────────────
  function crmGanttEnsureState() {
    if (!window.CRM) window.CRM = {};
    if (!window.CRM.ganttState) {
      var savedZoom = readCookie('crm_gantt_zoom');
      var initialZoom = (savedZoom && ['days', 'weeks', 'months'].indexOf(savedZoom) !== -1)
        ? savedZoom
        : (window.CRM.ganttZoom || 'weeks');

      window.CRM.ganttState = {
        zoom: initialZoom,
        kpiFilter: 'all',
        statusFilters: [],
        collapsedProjects: {}
      };
    }
    return window.CRM.ganttState;
  }

  function crmGanttDisposeTooltips(root) {
    if (!window.bootstrap || !window.bootstrap.Tooltip || !root) return;
    root.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function (node) {
      var instance = window.bootstrap.Tooltip.getInstance(node);
      if (instance) instance.dispose();
    });
  }

  function crmGanttRefreshTooltips() {
    var root = document.querySelector('.crm-gantt-page');
    if (!root) return;
    if (!window.bootstrap || !window.bootstrap.Tooltip) {
      root.querySelectorAll('[data-bs-title]').forEach(function (node) {
        node.setAttribute('title', node.getAttribute('data-bs-title') || '');
      });
      return;
    }
    root.querySelectorAll('[data-bs-toggle="tooltip"]').forEach(function (node) {
      var old = window.bootstrap.Tooltip.getInstance(node);
      if (old) old.dispose();
      new window.bootstrap.Tooltip(node, { container: 'body', boundary: document.body, trigger: 'hover focus' });
    });
  }
  // ─────────────────────────────────────────────────────────────

  function initGanttControls() {
    var state = crmGanttEnsureState();

    // Restore zoom from cookie
    var savedZoom = readCookie('crm_gantt_zoom');
    if (savedZoom && ['days', 'weeks', 'months'].indexOf(savedZoom) !== -1) {
      state.zoom = savedZoom;
      window.CRM.ganttZoom = savedZoom;
    } else if (!window.CRM.ganttZoom) {
      window.CRM.ganttZoom = state.zoom;
    }

    var buttons = document.querySelectorAll('[data-gantt-zoom]');
    buttons.forEach(function (button) {
      var mode = button.getAttribute('data-gantt-zoom') || 'weeks';
      var isActive = mode === state.zoom;
      button.classList.toggle('active', isActive);
      button.setAttribute('aria-pressed', isActive ? 'true' : 'false');

      if (button.dataset.ganttZoomBound === '1') return;

      button.addEventListener('click', function () {
        var nextMode = button.getAttribute('data-gantt-zoom') || 'weeks';
        var s = crmGanttEnsureState();
        s.zoom = nextMode;
        window.CRM.ganttZoom = nextMode;

        // Save zoom to cookie (30 days)
        document.cookie = 'crm_gantt_zoom=' + nextMode + '; path=/; max-age=2592000';

        document.querySelectorAll('[data-gantt-zoom]').forEach(function (item) {
          var itemMode = item.getAttribute('data-gantt-zoom') || 'weeks';
          item.classList.toggle('active', itemMode === nextMode);
          item.setAttribute('aria-pressed', itemMode === nextMode ? 'true' : 'false');
        });

        renderGanttPage().catch(function (error) {
          console.error('Gantt render failed', error);
          if (typeof notify === 'function') notify('Не удалось перестроить диаграмму Ганта', 'error');
        });
      });

      button.dataset.ganttZoomBound = '1';
    });

    // Board interactions: hover-sync, collapse, filters — one-time delegation
    var board = document.querySelector('.crm-gantt-board');
    if (board && board.dataset.ganttInteractionsBound !== '1') {
      board.dataset.ganttInteractionsBound = '1';

      function crmGanttSetHoverInner(rowId, enabled) {
        if (!rowId) return;
        document.querySelectorAll('[data-gantt-row-id="' + rowId + '"]').forEach(function (el) {
          el.classList.toggle('is-gantt-hover', enabled);
        });
      }

      board.addEventListener('pointerover', function (e) {
        var t = e.target.closest('[data-gantt-row-id]');
        if (t) crmGanttSetHoverInner(t.getAttribute('data-gantt-row-id'), true);
      }, true);

      board.addEventListener('pointerout', function (e) {
        var t = e.target.closest('[data-gantt-row-id]');
        if (t) crmGanttSetHoverInner(t.getAttribute('data-gantt-row-id'), false);
      }, true);

      board.addEventListener('focusin', function (e) {
        var t = e.target.closest('[data-gantt-row-id]');
        if (t) crmGanttSetHoverInner(t.getAttribute('data-gantt-row-id'), true);
      }, true);

      board.addEventListener('focusout', function (e) {
        var t = e.target.closest('[data-gantt-row-id]');
        if (t) crmGanttSetHoverInner(t.getAttribute('data-gantt-row-id'), false);
      }, true);

      board.addEventListener('click', function (e) {
        var kpiBtn = e.target.closest('[data-gantt-kpi-filter]');
        if (kpiBtn) {
          var filter = kpiBtn.getAttribute('data-gantt-kpi-filter') || 'all';
          var ks = crmGanttEnsureState();
          ks.kpiFilter = ks.kpiFilter === filter ? 'all' : filter;
          renderGanttPage().catch(function (err) { console.error('Gantt rerender', err); });
          return;
        }
        var statusBtn = e.target.closest('[data-gantt-status-filter]');
        if (statusBtn) {
          var status = statusBtn.getAttribute('data-gantt-status-filter');
          var ss = crmGanttEnsureState();
          ss.statusFilters = ss.statusFilters || [];
          var idx = ss.statusFilters.indexOf(status);
          if (idx === -1) { ss.statusFilters.push(status); } else { ss.statusFilters.splice(idx, 1); }
          renderGanttPage().catch(function (err) { console.error('Gantt rerender', err); });
        }
      }, true);
    }
  }


  function crmGanttParseDate(value) {
    if (!value) return null;

    var timestamp = Date.parse(String(value));
    if (!isNaN(timestamp)) return timestamp;

    return null;
  }

  function crmGanttDateFromTask(task, fields) {
    for (var i = 0; i < fields.length; i++) {
      var timestamp = crmGanttParseDate(task[fields[i]]);
      if (timestamp !== null) return timestamp;
    }

    return null;
  }

  function crmGanttStartOfDay(timestamp) {
    var date = new Date(timestamp);
    date.setHours(0, 0, 0, 0);
    return date.getTime();
  }

  function crmGanttAddDays(timestamp, days) {
    return timestamp + days * 24 * 3600 * 1000;
  }

  function crmGanttClamp(value, min, max) {
    return Math.max(min, Math.min(max, value));
  }

  function crmGanttDateIso(timestamp) {
    return new Date(timestamp).toISOString();
  }

  function crmGanttPluralTasks(count) {
    var mod10 = count % 10;
    var mod100 = count % 100;

    if (mod10 === 1 && mod100 !== 11) return count + ' задача';
    if (mod10 >= 2 && mod10 <= 4 && (mod100 < 12 || mod100 > 14)) return count + ' задачи';

    return count + ' задач';
  }

  function crmGanttFormatShortDateValue(value) {
    if (!value) return '';

    var date = value instanceof Date ? value : new Date(value);

    if (isNaN(date.getTime())) {
      return '';
    }

    return date.toLocaleDateString('ru-RU', {
      day: 'numeric',
      month: 'short'
    }).replace('.', '');
  }

  function crmGanttStatusKind(code) {
    var raw = String(code || '').toLowerCase();
    var css = String(statusClass(code) || '').toLowerCase();

    if (
      raw === 'done' ||
      raw === 'completed' ||
      raw === 'complete' ||
      raw === 'closed' ||
      raw === 'ready' ||
      raw === 'released' ||
      css.indexOf('success') !== -1
    ) {
      return 'success';
    }

    if (
      raw === 'blocked' ||
      raw === 'on_hold' ||
      raw === 'paused' ||
      css.indexOf('blocked') !== -1
    ) {
      return 'blocked';
    }

    if (
      raw === 'archived' ||
      raw === 'cancelled' ||
      raw === 'canceled' ||
      css.indexOf('archived') !== -1
    ) {
      return 'archived';
    }

    if (
      raw === 'review' ||
      raw === 'qa' ||
      raw === 'testing' ||
      raw === 'ready_for_release'
    ) {
      return 'review';
    }

    return 'active';
  }

  function crmGanttNormalizeTask(task) {
    var DAY_MS = 24 * 3600 * 1000;

    var rawStart = crmGanttDateFromTask(task, [
      'start_at',
      'started_at',
      'planned_start_at',
      'actual_start_at'
    ]);
    var rawEnd = crmGanttDateFromTask(task, [
      'due_at',
      'deadline_at',
      'finish_at',
      'finished_at',
      'completed_at',
      'end_at',
      'planned_end_at'
    ]);
    var hasDates = !!rawStart || !!rawEnd;

    var start = rawStart;
    var end = rawEnd;

    if (start === null && end !== null) start = end - 2 * DAY_MS;
    if (start !== null && end === null) end = start + 2 * DAY_MS;
    if (start === null && end === null) {
      start = crmGanttStartOfDay(Date.now());
      end = start + 2 * DAY_MS;
    }

    if (end < start) {
      var tmp = start;
      start = end;
      end = tmp;
    }

    if (end === start) {
      end = start + DAY_MS;
    }

    var projectTitle = String(task.project_title || task.project_name || 'Без проекта');
    var projectId = String(task.project_public_id || projectTitle);

    return {
      task: task,
      id: String(task.public_id || ''),
      title: String(task.title || task.name || task.public_id || 'Без названия'),
      projectId: projectId,
      projectTitle: projectTitle,
      statusCode: String(task.status_code || task.status || 'new'),
      priorityCode: String(task.priority_code || task.priority || ''),
      assignee: String(task.assignee_name || task.responsible_name || task.owner_name || ''),
      hasDates: hasDates,
      start: start,
      end: end,
      due: end,
      kind: crmGanttStatusKind(task.status_code || task.status || 'new'),
      statusKind: crmGanttStatusKind(task.status_code || task.status || 'new'),
      isOverdue: end < crmGanttStartOfDay(Date.now()) && !['done', 'completed', 'closed', 'archived'].includes(String(task.status_code || task.status || '').toLowerCase()),
      isBlocked: ['blocked', 'on_hold', 'paused'].includes(String(task.status_code || task.status || '').toLowerCase())
    };
  }

  function crmGanttBuildWindow(items, zoomMode) {
    var DAY_MS = 24 * 3600 * 1000;

    var minStart = Math.min.apply(null, items.map(function (item) { return item.start; }));
    var maxEnd = Math.max.apply(null, items.map(function (item) { return item.end; }));

    var padDays = zoomMode === 'days' ? 2 : (zoomMode === 'weeks' ? 7 : 20);
    minStart = crmGanttStartOfDay(crmGanttAddDays(minStart, -padDays));
    maxEnd = crmGanttStartOfDay(crmGanttAddDays(maxEnd, padDays));

    if (zoomMode === 'months') {
      var from = new Date(minStart);
      from.setDate(1);
      from.setHours(0, 0, 0, 0);
      minStart = from.getTime();

      var to = new Date(maxEnd);
      to.setDate(1);
      to.setMonth(to.getMonth() + 1);
      to.setHours(0, 0, 0, 0);
      maxEnd = to.getTime();
    }

    var stepDays = zoomMode === 'days' ? 1 : (zoomMode === 'weeks' ? 7 : 30);
    var cellWidth = zoomMode === 'days' ? 74 : (zoomMode === 'weeks' ? 112 : 132);
    var ticks = [];
    var cursor = minStart;

    while (cursor <= maxEnd && ticks.length < 180) {
      ticks.push(cursor);

      if (zoomMode === 'months') {
        var date = new Date(cursor);
        date.setMonth(date.getMonth() + 1);
        cursor = date.getTime();
      } else {
        cursor = crmGanttAddDays(cursor, stepDays);
      }
    }

    if (ticks.length < 2) {
      ticks.push(crmGanttAddDays(minStart, stepDays));
    }

    // Ensure track is wide enough: recalculate cellWidth if ticks are few
    var minTrackWidth = 900;
    if (ticks.length > 0) {
      cellWidth = Math.max(cellWidth, Math.ceil(minTrackWidth / ticks.length));
    }
    var trackWidth = Math.max(minTrackWidth, ticks.length * cellWidth);

    var trackEnd = zoomMode === 'months'
      ? (function () {
        var date = new Date(ticks[ticks.length - 1]);
        date.setMonth(date.getMonth() + 1);
        return date.getTime();
      })()
      : crmGanttAddDays(ticks[ticks.length - 1], stepDays);

    return {
      start: minStart,
      end: Math.max(trackEnd, maxEnd),
      ticks: ticks,
      stepDays: stepDays,
      cellWidth: cellWidth,
      trackWidth: trackWidth
    };
  }

  function crmGanttFormatScaleLabel(timestamp, zoomMode) {
    var date = new Date(timestamp);
    var months = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

    if (zoomMode === 'months') {
      return date.toLocaleDateString('ru-RU', {
        month: 'short',
        year: 'numeric'
      });
    }

    if (zoomMode === 'weeks') {
      var weekEnd = crmGanttAddDays(timestamp, 6);
      var startDate = new Date(timestamp);
      var endDate = new Date(weekEnd);
      var startDay = startDate.getDate();
      var endDay = endDate.getDate();
      var startMonth = months[startDate.getMonth()];
      var endMonth = months[endDate.getMonth()];
      var label = startDate.getMonth() === endDate.getMonth()
        ? startDay + '–' + endDay + ' ' + startMonth
        : startDay + ' ' + startMonth + ' – ' + endDay + ' ' + endMonth;
      return label;
    }

    if (zoomMode === 'days') {
      var day = date.getDate();
      var weekday = ['вс', 'пн', 'вт', 'ср', 'чт', 'пт', 'сб'][date.getDay()];
      return day + '<br><small>' + weekday + '</small>';
    }

    return formatDate(crmGanttDateIso(timestamp));
  }

  function crmGanttGroupItems(items) {
    var map = {};
    var groups = [];

    items.forEach(function (item) {
      if (!map[item.projectId]) {
        map[item.projectId] = {
          id: item.projectId,
          title: item.projectTitle,
          items: [],
          start: item.start,
          end: item.end
        };
        groups.push(map[item.projectId]);
      }

      map[item.projectId].items.push(item);
      map[item.projectId].start = Math.min(map[item.projectId].start, item.start);
      map[item.projectId].end = Math.max(map[item.projectId].end, item.end);
    });

    groups.forEach(function (group) {
      group.items.sort(function (a, b) {
        if (a.start !== b.start) return a.start - b.start;
        return a.title.localeCompare(b.title);
      });

      group.totalCount = group.items.length;
      group.overdueCount = group.items.filter(function (item) { return item.isOverdue; }).length;
      group.blockedCount = group.items.filter(function (item) { return item.isBlocked; }).length;
      group.completedCount = group.items.filter(function (item) { return ['done', 'completed'].includes(item.statusCode); }).length;
      group.progressPercent = group.totalCount > 0 ? Math.round((group.completedCount / group.totalCount) * 100) : 0;
      group.dateRange = formatDate(crmGanttDateIso(group.start)) + ' — ' + formatDate(crmGanttDateIso(group.end));
    });

    groups.sort(function (a, b) {
      if (a.start !== b.start) return a.start - b.start;
      return a.title.localeCompare(b.title);
    });

    return groups;
  }

  function crmGanttPercent(timestamp, windowInfo) {
    var total = Math.max(1, windowInfo.end - windowInfo.start);
    return ((timestamp - windowInfo.start) / total) * 100;
  }

  function crmGanttCreateLaneBar(item, windowInfo, isProject) {
    var startPct = crmGanttClamp(crmGanttPercent(item.start, windowInfo), 0, 100);
    var endPct = crmGanttClamp(crmGanttPercent(item.end, windowInfo), 0, 100);
    var widthPct = Math.max(0.8, endPct - startPct);

    var href = item.id ? taskLink(item.id) : '#';
    var bar = document.createElement(item.id ? 'a' : 'div');

    bar.className = 'crm-gantt-bar crm-gantt-bar--' + item.kind + (isProject ? ' crm-gantt-bar--project' : '');
    bar.style.left = startPct + '%';
    bar.style.width = widthPct + '%';

    if (item.id) {
      bar.href = href;
    }

    bar.setAttribute('role', item.id ? 'link' : 'img');
    bar.setAttribute('aria-label', item.title + ': ' + formatDate(crmGanttDateIso(item.start)) + ' — ' + formatDate(crmGanttDateIso(item.end)));
    bar.setAttribute('data-bs-toggle', 'tooltip');
    bar.setAttribute('data-bs-placement', 'top');
    bar.setAttribute('title', item.title + '\n'
      + 'Проект: ' + item.projectTitle + '\n'
      + 'Статус: ' + statusLabel(item.statusCode) + '\n'
      + 'Срок: ' + formatDate(crmGanttDateIso(item.start)) + ' — ' + formatDate(crmGanttDateIso(item.end)));

    var title = document.createElement('span');
    title.className = 'crm-gantt-bar-title';
    title.textContent = isProject ? item.projectTitle : item.title;
    bar.appendChild(title);

    var dates = document.createElement('span');
    dates.className = 'crm-gantt-bar-dates';
    dates.textContent = formatDate(crmGanttDateIso(item.end));
    if (widthPct < 8) {
      dates.style.display = 'none';
    }
    bar.appendChild(dates);

    if (widthPct < 8) {
      bar.classList.add('crm-gantt-bar--compact');
    }

    if (widthPct < 4) {
      bar.classList.add('crm-gantt-bar--micro');
    }

    // Progress fill
    var progress = document.createElement('div');
    progress.className = 'crm-gantt-bar-progress';
    if (['done', 'completed'].includes(item.statusCode)) {
      progress.style.width = '100%';
    }
    bar.appendChild(progress);

    // Markers
    if (item.isOverdue) {
      var overdueMarker = document.createElement('span');
      overdueMarker.className = 'crm-gantt-bar-marker crm-gantt-bar-marker--overdue';
      overdueMarker.textContent = '!';
      bar.appendChild(overdueMarker);
    }

    if (item.isBlocked) {
      var blockedMarker = document.createElement('span');
      blockedMarker.className = 'crm-gantt-bar-marker crm-gantt-bar-marker--blocked';
      blockedMarker.textContent = '⚠';
      bar.appendChild(blockedMarker);
    }

    return bar;
  }

  // Enhanced bar with priority, progress text, and resize handle
  function crmGanttCreateLaneBarEnhanced(item, windowInfo, isProject) {
    var startPct = crmGanttClamp(crmGanttPercent(item.start, windowInfo), 0, 100);
    var endPct = crmGanttClamp(crmGanttPercent(item.end, windowInfo), 0, 100);
    var widthPct = Math.max(0.8, endPct - startPct);

    var href = item.id ? taskLink(item.id) : '#';
    var bar = document.createElement(item.id ? 'a' : 'div');

    bar.className = 'crm-gantt-bar crm-gantt-bar--' + item.kind + (isProject ? ' crm-gantt-bar--project' : '');

    // 4. Priority indicator
    if (item.priority && item.priority !== 'low' && !isProject) {
      bar.classList.add('crm-gantt-bar--priority-' + item.priority);
    }

    bar.style.left = startPct + '%';
    bar.style.width = widthPct + '%';

    if (item.id) {
      bar.href = href;
    }

    bar.setAttribute('role', item.id ? 'link' : 'img');
    bar.setAttribute('aria-label', item.title + ': ' + formatDate(crmGanttDateIso(item.start)) + ' — ' + formatDate(crmGanttDateIso(item.end)));
    bar.setAttribute('data-bs-toggle', 'tooltip');
    bar.setAttribute('data-bs-placement', 'top');
    bar.setAttribute('title', item.title + '\n'
      + 'Проект: ' + item.projectTitle + '\n'
      + 'Статус: ' + statusLabel(item.statusCode) + '\n'
      + 'Срок: ' + formatDate(crmGanttDateIso(item.start)) + ' — ' + formatDate(crmGanttDateIso(item.end)));

    var title = document.createElement('span');
    title.className = 'crm-gantt-bar-title';
    title.textContent = isProject ? item.projectTitle : item.title;
    bar.appendChild(title);

    var dates = document.createElement('span');
    dates.className = 'crm-gantt-bar-dates';
    dates.textContent = formatDate(crmGanttDateIso(item.end));
    if (widthPct < 8) {
      dates.style.display = 'none';
    }
    bar.appendChild(dates);

    if (widthPct < 8) {
      bar.classList.add('crm-gantt-bar--compact');
    }

    if (widthPct < 4) {
      bar.classList.add('crm-gantt-bar--micro');
    }

    // 8. Enhanced progress fill with percentage text
    var progress = document.createElement('div');
    progress.className = 'crm-gantt-bar-progress';
    var progressPercent = item.progressPercent || (['done', 'completed'].includes(item.statusCode) ? 100 : 0);
    progress.style.width = progressPercent + '%';
    bar.appendChild(progress);

    if (progressPercent > 0 && widthPct >= 8) {
      var progressText = document.createElement('span');
      progressText.className = 'crm-gantt-bar-progress-text';
      progressText.textContent = progressPercent + '%';
      bar.appendChild(progressText);
    }

    // Markers
    if (item.isOverdue) {
      var overdueMarker = document.createElement('span');
      overdueMarker.className = 'crm-gantt-bar-marker crm-gantt-bar-marker--overdue';
      overdueMarker.textContent = '!';
      bar.appendChild(overdueMarker);
    }

    if (item.isBlocked) {
      var blockedMarker = document.createElement('span');
      blockedMarker.className = 'crm-gantt-bar-marker crm-gantt-bar-marker--blocked';
      blockedMarker.textContent = '⚠';
      bar.appendChild(blockedMarker);
    }

    // 5. Resize handle on the right edge
    if (!isProject && item.id) {
      var resizeHandle = document.createElement('span');
      resizeHandle.className = 'crm-gantt-bar-resize-handle';
      resizeHandle.style.cssText = 'position:absolute;right:0;top:0;bottom:0;width:8px;cursor:ew-resize;z-index:3;';
      bar.appendChild(resizeHandle);
    }

    return bar;
  }

  function crmGanttCreateGrid(windowInfo) {
    var grid = document.createElement('div');
    grid.className = 'crm-gantt-grid';
    grid.style.backgroundSize = windowInfo.cellWidth + 'px 100%';
    return grid;
  }

  function crmGanttCreateTodayLine(windowInfo) {
    var now = crmGanttStartOfDay(Date.now());

    if (now < windowInfo.start || now > windowInfo.end) {
      return null;
    }

    var line = document.createElement('div');
    line.className = 'crm-gantt-today-line';
    line.style.left = crmGanttPercent(now, windowInfo) + '%';
    line.style.zIndex = '0';

    return line;
  }

  function crmGanttRenderScale(scaleTrack, windowInfo, zoomMode) {
    scaleTrack.innerHTML = '';

    if (zoomMode === 'weeks' && windowInfo.ticks.length > 1) {
      // Build month ticks for upper level
      var monthTicks = [];
      var currentMonth = null;
      windowInfo.ticks.forEach(function (tick) {
        var month = new Date(tick).getMonth();
        var year = new Date(tick).getFullYear();
        var monthKey = year + '-' + month;
        if (monthKey !== currentMonth) {
          monthTicks.push(tick);
          currentMonth = monthKey;
        }
      });

      if (monthTicks.length > 1) {
        var monthDiv = document.createElement('div');
        monthDiv.className = 'crm-gantt-scale-months';
        monthDiv.style.gridTemplateColumns = 'repeat(' + windowInfo.ticks.length + ', minmax(' + windowInfo.cellWidth + 'px, ' + windowInfo.cellWidth + 'px))';
        for (var i = 0; i < monthTicks.length; i++) {
          var startIndex = windowInfo.ticks.indexOf(monthTicks[i]);
          var endIndex = (i + 1 < monthTicks.length) ? windowInfo.ticks.indexOf(monthTicks[i + 1]) : windowInfo.ticks.length;
          var spanCount = endIndex - startIndex;
          var span = document.createElement('span');
          span.textContent = crmGanttFormatScaleLabel(monthTicks[i], 'months');
          span.style.gridColumn = 'span ' + spanCount;
          monthDiv.appendChild(span);
        }
        scaleTrack.appendChild(monthDiv);
      }
    }

    var mainDiv = document.createElement('div');
    mainDiv.className = 'crm-gantt-scale-main';
    mainDiv.style.gridTemplateColumns = 'repeat(' + windowInfo.ticks.length + ', minmax(' + windowInfo.cellWidth + 'px, ' + windowInfo.cellWidth + 'px))';

    var today = crmGanttStartOfDay(Date.now());
    windowInfo.ticks.forEach(function (timestamp) {
      var item = document.createElement('span');
      item.innerHTML = crmGanttFormatScaleLabel(timestamp, zoomMode);
      if (zoomMode === 'days') {
        var date = new Date(timestamp);
        if (date.getDay() === 0 || date.getDay() === 6) {
          item.className = 'text-muted';
        }
      }
      var periodEnd = zoomMode === 'weeks' ? crmGanttAddDays(timestamp, 7) : crmGanttAddDays(timestamp, 1);
      if (timestamp <= today && today < periodEnd) {
        item.classList.add('crm-gantt-scale-current');
      }
      mainDiv.appendChild(item);
    });

    scaleTrack.appendChild(mainDiv);

    // Today label in scale
    if (today >= windowInfo.start && today <= windowInfo.end) {
      var todayLabel = document.createElement('div');
      todayLabel.className = 'crm-gantt-today-scale-label';
      todayLabel.textContent = 'Сегодня';
      todayLabel.style.left = crmGanttPercent(today, windowInfo) + '%';
      scaleTrack.appendChild(todayLabel);
    }
  }

  function crmGanttRenderScaleDual(scaleTrack, windowInfo, zoomMode) {
    crmGanttRenderScale(scaleTrack, windowInfo, zoomMode);
  }

  function crmGanttRenderLegend(tasks, legendEl) {
    if (!legendEl) return;

    var counts = {};
    tasks.forEach(function (task) {
      var code = String(task.status_code || task.status || 'new');
      if (!counts[code]) counts[code] = 0;
      counts[code]++;
    });

    var codes = Object.keys(counts).sort(function (a, b) {
      return statusLabel(a).localeCompare(statusLabel(b));
    });

    var state = crmGanttEnsureState();
    var activeStatuses = state.statusFilters || [];

    legendEl.innerHTML = codes.map(function (code) {
      var kind = crmGanttStatusKind(code);
      var isActive = activeStatuses.indexOf(code) !== -1;

      return '<span class="crm-chip crm-chip-status"'
        + ' data-gantt-status-filter="' + safeText(code) + '"'
        + ' aria-pressed="' + (isActive ? 'true' : 'false') + '"'
        + '>'
        + '<span class="crm-chip-dot crm-chip-dot--' + kind + '"></span>'
        + safeText(statusLabel(code)) + ' (' + counts[code] + ')'
        + '</span>';
    }).join('') || '<span class="crm-chip">Нет задач</span>';
  }

  function applyGanttFilter(items, filter) {
    if (filter === 'all') return items;
    return items.filter(function (item) {
      if (filter === 'active') return !['completed', 'done', 'archived'].includes(item.statusCode);
      if (filter === 'overdue') return item.isOverdue;
      if (filter === 'blocked') return item.isBlocked;
      if (filter === 'completed') return ['completed', 'done'].includes(item.statusCode);
      if (filter === 'without_dates') return !item.start || !item.end;
      return true;
    });
  }

  function crmGanttRenderKpis(items, tilesEl, withoutDates) {
    if (!tilesEl) return;

    var now = crmGanttStartOfDay(Date.now());
    var active = 0;
    var overdue = 0;
    var blocked = 0;
    var done = 0;

    items.forEach(function (item) {
      if (item.kind === 'success' || item.kind === 'archived') {
        done++;
        return;
      }

      active++;

      if (item.kind === 'blocked') {
        blocked++;
      }

      if (item.end < now) {
        overdue++;
      }
    });

    var currentFilter = window.CRM.ganttFilter || 'all';

    tilesEl.innerHTML = ''
      + '<div class="crm-gantt-kpi-card' + (currentFilter === 'all' ? ' active' : '') + '" data-gantt-filter="all">'
      + '<small>Всего задач</small>'
      + '<strong>' + items.length + '</strong>'
      + '<span>Общий список</span>'
      + '</div>'
      + '<div class="crm-gantt-kpi-card' + (currentFilter === 'active' ? ' active' : '') + '" data-gantt-filter="active">'
      + '<small>Активные задачи</small>'
      + '<strong>' + active + '</strong>'
      + '<span>В работе и ожидании</span>'
      + '</div>'
      + '<div class="crm-gantt-kpi-card is-warning' + (currentFilter === 'overdue' ? ' active' : '') + '" data-gantt-filter="overdue">'
      + '<small>Риски по срокам</small>'
      + '<strong>' + overdue + '</strong>'
      + '<span>Просрочено относительно дедлайна</span>'
      + '</div>'
      + '<div class="crm-gantt-kpi-card is-danger' + (currentFilter === 'blocked' ? ' active' : '') + '" data-gantt-filter="blocked">'
      + '<small>Блокировки</small>'
      + '<strong>' + blocked + '</strong>'
      + '<span>Требуют внимания</span>'
      + '</div>'
      + '<div class="crm-gantt-kpi-card is-success' + (currentFilter === 'completed' ? ' active' : '') + '" data-gantt-filter="completed">'
      + '<small>Завершено</small>'
      + '<strong>' + done + '</strong>'
      + '<span>Готово или закрыто</span>'
      + '</div>'
      + '<div class="crm-gantt-kpi-card' + (currentFilter === 'without_dates' ? ' active' : '') + '" data-gantt-filter="without_dates">'
      + '<small>Без дат</small>'
      + '<strong>' + (withoutDates || 0) + '</strong>'
      + '<span>Не запланировано</span>'
      + '</div>';
  }

  function crmGanttRenderMilestones(items, milestonesEl) {
    if (!milestonesEl) return;

    var now = crmGanttStartOfDay(Date.now());
    var months = ['янв','фев','мар','апр','май','июн','июл','авг','сен','окт','ноя','дек'];
    var upcoming = items
      .filter(function (item) {
        return item.kind !== 'success' && item.kind !== 'archived';
      })
      .sort(function (a, b) {
        var da = a.end - now;
        var db = b.end - now;
        return da - db;
      })
      .slice(0, 6);

    if (!upcoming.length) {
      milestonesEl.innerHTML = '<div class="crm-gantt-deadline-card" style="justify-content:center;color:#64748b;font-size:0.82rem;">Нет ближайших сроков</div>';
      return;
    }

    milestonesEl.innerHTML = upcoming.map(function (item) {
      var days = Math.ceil((crmGanttStartOfDay(item.end) - now) / (24 * 3600 * 1000));
      var stateLabel = days < 0 ? 'Просрочено' : (days === 0 ? 'Сегодня' : days + ' дн.');
      var stateKind = days < 0 ? 'blocked' : (days === 0 ? 'active' : 'review');
      var endDate = new Date(item.end);

      return '<a class="crm-gantt-deadline-card crm-gantt-deadline-card--' + stateKind + '" href="' + taskLink(item.id) + '">'
        + '<span class="crm-gantt-deadline-date">'
        + '<strong>' + safeText(String(endDate.getDate())) + '</strong>'
        + '<small>' + safeText(months[endDate.getMonth()]) + '</small>'
        + '</span>'
        + '<span class="crm-gantt-deadline-main">'
        + '<strong>' + safeText(item.title) + '</strong>'
        + '<small>' + safeText(item.projectTitle) + '</small>'
        + '<em>' + safeText(stateLabel) + '</em>'
        + '</span>'
        + '</a>';
    }).join('');
  }

  function crmGanttRenderStatusSummary(items, summaryEl) {
    if (!summaryEl) return;

    if (!items.length) {
      summaryEl.innerHTML = '<div class="crm-metric-tile">Нет данных для сводки.</div>';
      return;
    }

    var now = crmGanttStartOfDay(Date.now());
    var minStart = Math.min.apply(null, items.map(function (item) { return item.start; }));
    var maxEnd = Math.max.apply(null, items.map(function (item) { return item.end; }));

    var projects = {};
    items.forEach(function (item) {
      projects[item.projectId] = true;
    });

    summaryEl.innerHTML = ''
      + '<div class="crm-gantt-summary-grid">'
      + '<div class="crm-metric-tile">'
      + '<small>Проекты</small>'
      + '<strong>' + Object.keys(projects).length + '</strong>'
      + '</div>'
      + '<div class="crm-metric-tile">'
      + '<small>Задачи с датами</small>'
      + '<strong>' + items.length + '</strong>'
      + '</div>'
      + '<div class="crm-metric-tile">'
      + '<small>Просрочено</small>'
      + '<strong class="is-danger">' + items.filter(function (it) { return it.end < now; }).length + '</strong>'
      + '</div>'
      + '<div class="crm-metric-tile">'
      + '<small>Диапазон</small>'
      + '<strong>' + safeText(crmGanttFormatShortDateValue(minStart)) + ' — ' + safeText(crmGanttFormatShortDateValue(maxEnd)) + '</strong>'
      + '</div>'
      + '</div>';
  }

  function crmGanttInitBootstrapTooltips(root) {
    if (!window.bootstrap || typeof window.bootstrap.Tooltip !== 'function') return;

    var nodes = (root || document).querySelectorAll('[data-bs-toggle="tooltip"]');

    nodes.forEach(function (node) {
      if (node.dataset.tooltipBound === '1') return;

      try {
        new window.bootstrap.Tooltip(node, {
          container: 'body',
          boundary: 'window'
        });
        node.dataset.tooltipBound = '1';
      } catch (error) {
        console.warn('Tooltip init failed', error);
      }
    });
  }

  function crmGanttRenderKpiButtons(items, withoutDates, state) {
    var root = document.getElementById('ganttSummaryTiles');
    if (!root) return;

    items = Array.isArray(items) ? items : [];
    withoutDates = Array.isArray(withoutDates) ? withoutDates : [];
    state = state || {};

    var total = items.length;

    var active = items.filter(function (item) {
      var kind = String(item && item.statusKind ? item.statusKind : '');
      return kind !== 'success' && kind !== 'archived';
    }).length;

    var overdue = items.filter(function (item) {
      return !!(item && item.isOverdue);
    }).length;

    var blocked = items.filter(function (item) {
      return !!(item && item.isBlocked);
    }).length;

    var completed = items.filter(function (item) {
      return String(item && item.statusKind ? item.statusKind : '') === 'success';
    }).length;

    var cards = [
      { key: 'all', label: 'Всего задач', value: total, tone: 'new' },
      { key: 'active', label: 'Активные', value: active, tone: 'active' },
      { key: 'overdue', label: 'Просрочено', value: overdue, tone: 'overdue' },
      { key: 'blocked', label: 'Заблокировано', value: blocked, tone: 'blocked' },
      { key: 'completed', label: 'Завершено', value: completed, tone: 'success' },
      { key: 'without_dates', label: 'Без дат', value: withoutDates.length, tone: 'paused' }
    ];

    root.innerHTML = cards.map(function (card) {
      var isPressed = String(state.kpiFilter || 'all') === card.key;

      return ''
        + '<button type="button"'
        + ' class="crm-gantt-kpi-button crm-gantt-kpi-button--' + safeText(card.tone) + '"'
        + ' data-gantt-kpi-filter="' + safeText(card.key) + '"'
        + ' aria-pressed="' + (isPressed ? 'true' : 'false') + '">'
        + '<strong>' + String(card.value) + '</strong>'
        + '<small>' + safeText(card.label) + '</small>'
        + '</button>';
    }).join('');
  }

  function crmGanttBindProjectCollapse() {
    var board = document.querySelector('.crm-gantt-board');
    if (!board || board.dataset.ganttProjectCollapseBound === '1') return;

    board.addEventListener('click', function (e) {
      var btn = e.target.closest('[data-gantt-project-toggle]');
      if (!btn) return;

      e.preventDefault();
      var collapsed = crmGanttGetCollapsedProjects();
      var projectId = btn.getAttribute('data-gantt-project-toggle');
      collapsed[projectId] = !collapsed[projectId];

      renderGanttPage().catch(function (error) {
        console.error('[GANTT] project collapse render failed', error);
      });
    });

    board.dataset.ganttProjectCollapseBound = '1';
  }

  async function renderGanttPage() {
    var state = crmGanttEnsureState();
    var tasksEnvelope = await tryRequest('api/v1/tasks', { query: { limit: 200 } });

    var legendEl    = document.getElementById('ganttLegend');
    var tilesEl     = document.getElementById('ganttSummaryTiles');
    var summaryEl   = document.getElementById('ganttStatusSummary');
    var milestonesEl = document.getElementById('ganttMilestonesList');
    var rowsContainer = document.querySelector('.crm-gantt .crm-gantt-rows');
    var lanesContainer = document.querySelector('.crm-gantt .crm-gantt-lanes');
    var scaleTrack  = document.getElementById('ganttScaleTrack');
    var board       = document.querySelector('.crm-gantt-board');
    var ganttPage   = document.querySelector('.crm-gantt-page');
    var mobileModeButtons = document.querySelectorAll('[data-gantt-mobile-mode]');
    var mobileListMode = document.getElementById('ganttMobileListMode');
    var isMobile = window.matchMedia && window.matchMedia('(max-width: 767.98px)').matches;
    if (!state.mobileMode) state.mobileMode = 'list';
    if (!isMobile) state.mobileMode = 'timeline';

    if (!tasksEnvelope || tasksEnvelope.success === false) {
      if (legendEl) legendEl.innerHTML = '<span class="crm-chip text-danger">Ошибка загрузки</span>';
      if (milestonesEl) milestonesEl.innerHTML = '<p class="text-danger mb-0">Ошибка загрузки задач</p>';
      if (summaryEl) summaryEl.innerHTML = '<div class="crm-metric-tile text-danger">Не удалось загрузить график.</div>';
      return;
    }

    // ── Нормализация ─────────────────────────────────────────
    var allRaw = mapItems(tasksEnvelope);
    var allItems = allRaw.map(crmGanttNormalizeTask).filter(function (item) {
      return item.id || item.title;
    });

    // 4. Add priority info to normalized items
    allItems.forEach(function (item) {
      var rawPriority = String(item.task.priority_code || item.task.priority || '').toLowerCase();
      item.priority = rawPriority === 'high' || rawPriority === 'urgent' ? 'high'
        : rawPriority === 'medium' || rawPriority === 'normal' ? 'medium'
        : 'low';
      // Progress percent from task data
      item.progressPercent = parseInt(item.task.progress_percent || item.task.progress || 0, 10) || 0;
    });

    // ── Применяем фильтры из state ────────────────────────────
    var activeFilter = state.kpiFilter || (window.CRM && window.CRM.ganttKpiFilter) || 'all';

    // Base scope for combined filters: search + project
    var scopedItems = allItems.slice();
    if (state.searchQuery) {
      scopedItems = crmGanttApplySearch(scopedItems, state.searchQuery);
    }
    if (state.projectFilter) {
      scopedItems = scopedItems.filter(function (item) { return item.projectId === state.projectFilter; });
    }

    // Legend should react to project/search and KPI filter, but keep status chips available.
    var legendItems = applyGanttFilter(scopedItems, activeFilter);

    // Status filter applies next and affects KPI numbers + chart.
    var statusScopedItems = legendItems.slice();
    if (state.statusFilters && state.statusFilters.length) {
      statusScopedItems = statusScopedItems.filter(function (item) {
        return state.statusFilters.indexOf(item.statusCode) !== -1;
      });
    }

    // KPI numbers should react to all current filters except KPI itself.
    var kpiItems = scopedItems.slice();
    if (state.statusFilters && state.statusFilters.length) {
      kpiItems = kpiItems.filter(function (item) {
        return state.statusFilters.indexOf(item.statusCode) !== -1;
      });
    }

    // Final dataset for chart includes KPI filter too.
    var items = applyGanttFilter(statusScopedItems, activeFilter);

    // ── KPI ───────────────────────────────────────────────────
    crmGanttRenderKpiButtons(kpiItems, kpiItems.filter(function (item) { return !item.hasDates; }), { kpiFilter: activeFilter });

    // ── Легенда ───────────────────────────────────────────────
    crmGanttRenderLegend(legendItems.map(function (item) {
      return { status_code: item.statusCode, status: item.statusCode };
    }), legendEl);

    // ── Сроки и сводка ────────────────────────────────────────
    crmGanttRenderMilestones(items, milestonesEl);
    crmGanttRenderStatusSummary(items, summaryEl);

    if (mobileListMode) {
      function toDueTs(value) {
        if (value instanceof Date) return value.getTime();
        if (typeof value === 'number' && Number.isFinite(value)) return value;
        if (typeof value === 'string' && value.trim()) {
          var parsed = Date.parse(value);
          return Number.isNaN(parsed) ? Number.MAX_SAFE_INTEGER : parsed;
        }
        return Number.MAX_SAFE_INTEGER;
      }

      var listItems = items.slice().sort(function (a, b) {
        var aDue = toDueTs(a && a.end);
        var bDue = toDueTs(b && b.end);
        return aDue - bDue;
      }).slice(0, 12);
      if (!listItems.length) {
        mobileListMode.innerHTML = '<div class="crm-empty-state"><strong>Нет задач с датами</strong><p class="mb-0">Добавьте старт и дедлайн, чтобы видеть список ближайших сроков.</p></div>';
      } else {
        mobileListMode.innerHTML = listItems.map(function (item) {
          var due = item.end ? crmGanttFormatShortDateValue(item.end) : 'без даты';
          var status = statusLabel(item.statusCode || 'new');
          return '<a class="crm-gantt-deadline-card crm-gantt-deadline-card--' + safeText(item.statusKind || 'new') + '" href="' + taskLink(item.id) + '">'
            + '<span class="crm-gantt-deadline-date">' + safeText(due) + '</span>'
            + '<span class="crm-gantt-deadline-main"><strong>' + safeText(item.title || 'Без названия') + '</strong><small>' + safeText(status) + '</small></span>'
            + '</a>';
        }).join('');
      }
    }

    Array.prototype.slice.call(mobileModeButtons || []).forEach(function (btn) {
      if (btn.dataset.bound !== '1') {
        btn.dataset.bound = '1';
        btn.addEventListener('click', function () {
          var next = String(btn.getAttribute('data-gantt-mobile-mode') || 'list');
          if (state.mobileMode === next) return;
          state.mobileMode = next;
          renderGanttPage().catch(function (err) {
            console.error('[GANTT] mobile mode rerender', err);
          });
        });
      }
      btn.classList.toggle('is-active', String(btn.getAttribute('data-gantt-mobile-mode') || '') === state.mobileMode);
    });

    if (ganttPage) {
      ganttPage.setAttribute('data-gantt-mobile-mode', isMobile ? state.mobileMode : 'timeline');
    }

    if (isMobile) {
      if (board) board.classList.toggle('d-none', state.mobileMode !== 'timeline');
      if (mobileListMode) mobileListMode.classList.toggle('d-none', state.mobileMode !== 'list');
    } else {
      if (board) board.classList.remove('d-none');
      if (mobileListMode) mobileListMode.classList.add('d-none');
    }

    if (!rowsContainer || !lanesContainer || !scaleTrack || !board) return;

    // Dispose tooltips before clearing DOM
    crmGanttDisposeTooltips(board);

    rowsContainer.innerHTML  = '';
    lanesContainer.innerHTML = '';
    scaleTrack.innerHTML     = '';

    if (!items.length) {
      var hasScopedFilter = Boolean(state.searchQuery || state.projectFilter || activeFilter !== 'all' || (state.statusFilters && state.statusFilters.length));
      scaleTrack.innerHTML = '<span class="text-muted small px-3">Нет задач</span>';
      rowsContainer.innerHTML  = '<div class="crm-gantt-row crm-gantt-row--empty"><strong>' + (hasScopedFilter ? 'Нет задач по выбранным фильтрам' : 'Нет задач для отображения') + '</strong></div>';
      lanesContainer.innerHTML = '<div class="crm-gantt-lane crm-gantt-lane--empty"><span class="crm-chip">' + (hasScopedFilter ? 'Очистите поиск или фильтры, чтобы вернуть задачи' : 'Создайте задачу с датами начала и завершения') + '</span></div>';
      // Still populate project filter with all projects
      var allGroups = crmGanttGroupItems(allItems);
      crmGanttPopulateProjectFilter(allGroups);
      return;
    }

    // ── Шкала ────────────────────────────────────────────────
    var zoomMode = state.zoom || 'weeks';
    var windowInfo = crmGanttBuildWindow(items, zoomMode);
    state._windowInfo = windowInfo; // store for drag-and-drop
    var groups = crmGanttGroupItems(items);

    // Store all groups (from unfiltered items) for project filter dropdown
    var allGroups = crmGanttGroupItems(allItems);
    state._allGroups = allGroups;

    board.style.setProperty('--gantt-track-width', windowInfo.trackWidth + 'px');
    board.style.setProperty('--gantt-cell-width',  windowInfo.cellWidth  + 'px');

    crmGanttRenderScaleDual(scaleTrack, windowInfo, zoomMode);

    // 7. Populate project filter with ALL projects (not filtered)
    crmGanttPopulateProjectFilter(allGroups);

    // ── Строки и дорожки ─────────────────────────────────────
    groups.forEach(function (group) {
      var isCollapsed = !!crmGanttGetCollapsedProjects()[group.id];

      // Project row
      var projectRow = document.createElement('div');
      projectRow.className = 'crm-gantt-row crm-gantt-row--project';
      projectRow.setAttribute('data-gantt-row-id', 'project-' + group.id);
      projectRow.setAttribute('data-gantt-project-id', group.id);

      var completedCount = group.items.filter(function (it) {
        return ['done', 'completed'].indexOf(it.statusCode) !== -1;
      }).length;
      var progressPct = group.totalCount > 0 ? Math.round(completedCount / group.totalCount * 100) : 0;

      projectRow.innerHTML = ''
        + '<div class="crm-gantt-row-main">'
        + '<button class="crm-gantt-project-toggle" data-gantt-project-toggle="' + safeText(group.id) + '" aria-expanded="' + (!isCollapsed) + '">'
        + '<span class="crm-gantt-chevron">' + (isCollapsed ? '▶' : '▼') + '</span>'
        + '<strong>' + safeText(group.title) + '</strong>'
        + '</button>'
        + '<div class="crm-gantt-row-meta">'
        + safeText(crmGanttPluralTasks(group.items.length))
        + (group.overdueCount ? ' · <span class="text-danger">' + group.overdueCount + ' просрочено</span>' : '')
        + ' · ' + progressPct + '%'
        + '</div>'
        + '</div>'
        + '<span class="crm-gantt-status-pill">' + progressPct + '% готово</span>';

      // Project lane
      var projectLane = document.createElement('div');
      projectLane.className = 'crm-gantt-lane crm-gantt-lane--project';
      projectLane.setAttribute('data-gantt-row-id', 'project-' + group.id);
      projectLane.setAttribute('data-gantt-project-id', group.id);
      projectLane.appendChild(crmGanttCreateGrid(windowInfo));

      var todayLineP = crmGanttCreateTodayLine(windowInfo);
      if (todayLineP) projectLane.appendChild(todayLineP);

      // Project summary bar (progress-filled)
      var projBarWrap = document.createElement('div');
      projBarWrap.className = 'crm-gantt-project-bar';
      var pStartPct = crmGanttClamp(crmGanttPercent(group.start, windowInfo), 0, 100);
      var pEndPct   = crmGanttClamp(crmGanttPercent(group.end,   windowInfo), 0, 100);
      projBarWrap.style.left  = pStartPct + '%';
      projBarWrap.style.width = Math.max(1, pEndPct - pStartPct) + '%';
      var projBarFill = document.createElement('span');
      projBarFill.className = 'crm-gantt-project-bar-fill';
      projBarFill.style.width = progressPct + '%';
      projBarWrap.appendChild(projBarFill);
      projectLane.appendChild(projBarWrap);

      rowsContainer.appendChild(projectRow);
      lanesContainer.appendChild(projectLane);

      // Task rows — always render, use CSS class for collapse animation
      group.items.forEach(function (item) {
        var row = document.createElement('div');
        row.className = 'crm-gantt-row crm-gantt-row--task';
        row.setAttribute('data-gantt-row-id', 'task-' + item.id);
        row.setAttribute('data-gantt-project-id', group.id);

        // 1. Collapse animation class
        if (isCollapsed) {
          row.classList.add('is-collapsed');
        }

        // 10. Adaptive row height for long titles
        var isTall = item.title.length > 50;
        if (isTall) {
          row.classList.add('is-tall');
        }

        var dateRange = item.start && item.end
          ? crmGanttFormatShortDateValue(item.start) + ' — ' + crmGanttFormatShortDateValue(item.end)
          : 'Даты не заданы';

        row.innerHTML = ''
          + '<div class="crm-gantt-row-main">'
          + '<strong><a href="' + taskLink(item.id) + '">' + safeText(item.title) + '</a></strong>'
          + '<div class="crm-gantt-row-meta">'
          + safeText(dateRange)
          + (item.assignee ? ' · ' + safeText(item.assignee) : '')
          + '</div>'
          + '</div>'
          + '<span class="crm-gantt-status-pill ' + safeText(statusClass(item.statusCode)) + '">'
          + safeText(statusLabel(item.statusCode))
          + '</span>';

        var lane = document.createElement('div');
        lane.className = 'crm-gantt-lane crm-gantt-lane--task';
        lane.setAttribute('data-gantt-row-id', 'task-' + item.id);
        lane.setAttribute('data-gantt-project-id', group.id);
        if (isTall) lane.classList.add('is-tall');
        if (isCollapsed) lane.classList.add('is-collapsed');
        lane.appendChild(crmGanttCreateGrid(windowInfo));

        var todayLineT = crmGanttCreateTodayLine(windowInfo);
        if (todayLineT) lane.appendChild(todayLineT);

        var bar = crmGanttCreateLaneBarEnhanced(item, windowInfo, false);
        bar.setAttribute('data-gantt-row-id', 'task-' + item.id);
        bar.setAttribute('data-task-id', item.id);
        lane.appendChild(bar);

        rowsContainer.appendChild(row);
        lanesContainer.appendChild(lane);
      });
    });

    // 2. Render dependency lines
    crmGanttRenderDependencies(groups, windowInfo);

    // 9. Render milestones on chart
    if (window.CRM && window.CRM.ganttMilestones) {
      crmGanttRenderMilestonesOnChart(window.CRM.ganttMilestones, windowInfo, groups);
    }

    // 5. Bind drag-and-drop
    crmGanttMakeBarsDraggable();

    crmGanttRefreshTooltips();
    crmGanttBindProjectCollapse();

    // Auto-scroll to today
    var todayLine = board.querySelector('.crm-gantt-today-line');
    if (todayLine) {
      var boardEl = board;
      var lineLeft = todayLine.offsetLeft;
      var boardWidth = boardEl.clientWidth;
      var scrollTarget = Math.max(0, lineLeft - boardWidth / 2);
      boardEl.scrollLeft = scrollTarget;
    }
  }

  // Load dependencies and milestones from API
  async function crmGanttLoadAdditionalData() {
    try {
      // Load dependencies (no project filter required) — silent, don't show errors
      var depsEnvelope = await tryRequest('api/v1/dependency/list', { query: { limit: 500 }, silent: true });
      if (depsEnvelope && depsEnvelope.success !== false) {
        var rawDeps = mapItems(depsEnvelope);
        window.CRM.ganttDependencies = rawDeps.map(function (d) {
          return {
            from_task_id: String(d.depends_on_task_public_id || d.to_task_public_id || ''),
            to_task_id: String(d.task_public_id || d.from_task_public_id || ''),
            dependency_type: String(d.dependency_type || d.type || 'FS')
          };
        }).filter(function (d) { return d.from_task_id && d.to_task_id; });
      }
    } catch (e) {
      console.warn('[GANTT] Failed to load dependencies', e);
    }

    try {
      // Load milestones — need project_public_id, so first get projects — silent
      var projectsEnvelope = await tryRequest('api/v1/projects', { query: { limit: 200 }, silent: true });
      if (projectsEnvelope && projectsEnvelope.success !== false) {
        var projects = mapItems(projectsEnvelope);
        var allMilestones = [];

        // Load milestones for each project (limit to first 10 to avoid too many requests)
        for (var i = 0; i < Math.min(projects.length, 10); i++) {
          var project = projects[i];
          var projectPublicId = String(project.public_id || '');
          if (!projectPublicId) continue;

          try {
            var msEnvelope = await tryRequest('api/v1/milestone/list', { query: { project_public_id: projectPublicId }, silent: true });
            if (msEnvelope && msEnvelope.success !== false) {
              var msItems = mapItems(msEnvelope);
              msItems.forEach(function (m) {
                m.project_id = projectPublicId;
                m.project_title = project.title || project.name || '';
              });
              allMilestones = allMilestones.concat(msItems.filter(function (m) {
                return m.due_at || m.due_date;
              }));
            }
          } catch (e) {
            // skip project if milestones fail
          }
        }

        window.CRM.ganttMilestones = allMilestones;
      }
    } catch (e) {
      console.warn('[GANTT] Failed to load milestones', e);
    }
  }

  // ===== GANTT ENHANCEMENTS V3 =====

  // 3. Search functionality
  function crmGanttBindSearch() {
    var input = document.getElementById('ganttSearchInput');
    var clearBtn = document.getElementById('ganttSearchClearBtn');
    if (!input || input.dataset.searchBound === '1') return;
    input.dataset.searchBound = '1';

    function syncClearButton() {
      if (!clearBtn) return;
      clearBtn.classList.toggle('d-none', !input.value.trim());
    }

    input.addEventListener('input', function () {
      var query = input.value.toLowerCase().trim();
      var state = crmGanttEnsureState();
      state.searchQuery = query;
      syncClearButton();
      renderGanttPage().catch(function (err) { console.error('[GANTT] search rerender', err); });
    });

    if (clearBtn && clearBtn.dataset.searchClearBound !== '1') {
      clearBtn.addEventListener('click', function () {
        var state = crmGanttEnsureState();
        input.value = '';
        state.searchQuery = '';
        syncClearButton();
        input.focus();
        renderGanttPage().catch(function (err) { console.error('[GANTT] clear search rerender', err); });
      });
      clearBtn.dataset.searchClearBound = '1';
    }

    syncClearButton();
  }

  function crmGanttApplySearch(items, query) {
    if (!query) return items;
    return items.filter(function (item) {
      return (item.title || '').toLowerCase().indexOf(query) !== -1
        || (item.assignee || '').toLowerCase().indexOf(query) !== -1
        || (item.projectTitle || '').toLowerCase().indexOf(query) !== -1;
    });
  }

  // 7. Project filter
  function crmGanttPopulateProjectFilter(groups) {
    var select = document.getElementById('ganttProjectFilter');
    if (!select) return;

    var currentValue = select.value;
    var options = '<option value="all">Все проекты</option>';
    groups.forEach(function (group) {
      var selected = group.id === currentValue ? ' selected' : '';
      options += '<option value="' + safeText(group.id) + '"' + selected + '>' + safeText(group.title) + '</option>';
    });
    select.innerHTML = options;

    if (select.dataset.filterBound !== '1') {
      select.dataset.filterBound = '1';
      select.addEventListener('change', function () {
        var state = crmGanttEnsureState();
        state.projectFilter = select.value === 'all' ? null : select.value;
        renderGanttPage().catch(function (err) { console.error('[GANTT] project filter rerender', err); });
      });
    }
  }

  // 2. Dependency lines rendering
  function crmGanttRenderDependencies(groups, windowInfo) {
    var svg = document.getElementById('ganttDependenciesSvg');
    if (!svg) return;

    // Collect all tasks with their positions
    var taskPositions = {};
    groups.forEach(function (group) {
      group.items.forEach(function (item) {
        taskPositions[item.id] = item;
      });
    });

    // Load dependencies from state
    var dependencies = window.CRM && window.CRM.ganttDependencies ? window.CRM.ganttDependencies : [];
    if (!dependencies.length) {
      svg.innerHTML = '';
      return;
    }

    var lanesContainer = document.querySelector('.crm-gantt .crm-gantt-lanes');
    if (!lanesContainer) return;

    var lanes = lanesContainer.querySelectorAll('.crm-gantt-lane--task');
    var laneIndex = 0;
    var rowOffsets = {};

    groups.forEach(function (group) {
      group.items.forEach(function (item) {
        rowOffsets[item.id] = laneIndex;
        laneIndex++;
      });
    });

    var rowHeight = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--gantt-row-height')) || 72;
    var trackWidth = windowInfo.trackWidth;

    var paths = [];
    dependencies.forEach(function (dep) {
      var fromItem = taskPositions[dep.from_task_id];
      var toItem = taskPositions[dep.to_task_id];
      if (!fromItem || !toItem) return;

      var fromRow = rowOffsets[fromItem.id];
      var toRow = rowOffsets[toItem.id];
      if (fromRow === undefined || toRow === undefined) return;

      var fromStartPct = crmGanttClamp(crmGanttPercent(fromItem.start, windowInfo), 0, 100);
      var fromEndPct = crmGanttClamp(crmGanttPercent(fromItem.end, windowInfo), 0, 100);
      var toStartPct = crmGanttClamp(crmGanttPercent(toItem.start, windowInfo), 0, 100);

      var x1 = (fromEndPct / 100) * trackWidth;
      var y1 = fromRow * rowHeight + rowHeight / 2;
      var x2 = (toStartPct / 100) * trackWidth;
      var y2 = toRow * rowHeight + rowHeight / 2;

      var midX = x1 + Math.max(20, (x2 - x1) / 2);
      var isCritical = dep.dependency_type === 'FS';

      var d = 'M ' + x1 + ' ' + y1
        + ' C ' + midX + ' ' + y1 + ', ' + midX + ' ' + y2 + ', ' + x2 + ' ' + y2;

      paths.push('<path d="' + d + '"' + (isCritical ? ' class="is-critical"' : '') + '/>');

      // Arrow head
      var arrowSize = 6;
      var angle = Math.atan2(y2 - y1, x2 - x1);
      var ax1 = x2 - arrowSize * Math.cos(angle - Math.PI / 6);
      var ay1 = y2 - arrowSize * Math.sin(angle - Math.PI / 6);
      var ax2 = x2 - arrowSize * Math.cos(angle + Math.PI / 6);
      var ay2 = y2 - arrowSize * Math.sin(angle + Math.PI / 6);

      paths.push('<path d="M ' + ax1 + ' ' + ay1 + ' L ' + x2 + ' ' + y2 + ' L ' + ax2 + ' ' + ay2 + '"' + (isCritical ? ' class="is-critical"' : '') + ' fill="none"/>');
    });

    svg.setAttribute('width', trackWidth);
    svg.setAttribute('height', laneIndex * rowHeight);
    svg.innerHTML = paths.join('');
  }

  // 9. Milestones rendering on chart
  function crmGanttRenderMilestonesOnChart(milestones, windowInfo, groups) {
    var lanesContainer = document.querySelector('.crm-gantt .crm-gantt-lanes');
    if (!lanesContainer || !milestones || !milestones.length) return;

    var rowHeight = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--gantt-row-height')) || 72;
    var projectRowHeight = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--gantt-project-row-height')) || 54;

    // Build a map of project positions
    var projectPositions = {};
    var currentPosition = 0;
    groups.forEach(function (group, idx) {
      projectPositions[group.id] = currentPosition;
      currentPosition += projectRowHeight; // project lane
      currentPosition += group.items.length * rowHeight; // task lanes
    });

    milestones.forEach(function (milestone) {
      var dueTimestamp = Date.parse(String(milestone.due_at || milestone.due_date || ''));
      if (isNaN(dueTimestamp)) return;

      var pct = crmGanttClamp(crmGanttPercent(dueTimestamp, windowInfo), 0, 100);

      // Find the project position
      var yPos = 0;
      groups.forEach(function (group) {
        if (group.id === milestone.project_id || group.title === milestone.project_title) {
          yPos = projectPositions[group.id] + projectRowHeight / 2;
        }
      });

      var diamond = document.createElement('div');
      diamond.className = 'crm-gantt-milestone';
      diamond.style.left = pct + '%';
      diamond.style.top = yPos + 'px';
      diamond.setAttribute('data-bs-toggle', 'tooltip');
      diamond.setAttribute('data-bs-placement', 'top');
      diamond.setAttribute('title', milestone.title || 'Веха');

      var label = document.createElement('span');
      label.className = 'crm-gantt-milestone-label';
      label.textContent = milestone.title || '';
      diamond.appendChild(label);

      lanesContainer.appendChild(diamond);
    });
  }

  // 5. Drag-and-drop for date changes
  function crmGanttBindDragDrop() {
    var board = document.querySelector('.crm-gantt-board');
    if (!board || board.dataset.dragBound === '1') return;
    board.dataset.dragBound = '1';

    var dragState = null;

    board.addEventListener('pointerdown', function (e) {
      var bar = e.target.closest('.crm-gantt-bar.is-draggable');
      if (!bar) return;

      var resizeHandle = e.target.closest('.crm-gantt-bar-resize-handle');
      if (resizeHandle) {
        e.preventDefault();
        e.stopPropagation();
      }

      var lane = bar.closest('.crm-gantt-lane');
      if (!lane) return;

      var state = crmGanttEnsureState();
      var windowInfo = state._windowInfo || null;
      if (!windowInfo) return;

      dragState = {
        bar: bar,
        lane: lane,
        startX: e.clientX,
        startLeftPct: parseFloat(bar.style.left) || 0,
        startWidthPct: parseFloat(bar.style.width) || 1,
        isResize: !!resizeHandle,
        taskId: bar.getAttribute('data-task-id'),
        windowInfo: windowInfo
      };

      bar.classList.add('is-dragging');
      bar.setPointerCapture(e.pointerId);
    });

    board.addEventListener('pointermove', function (e) {
      if (!dragState) return;
      e.preventDefault();

      var laneRect = dragState.lane.getBoundingClientRect();
      var deltaX = e.clientX - dragState.startX;
      var deltaPct = (deltaX / laneRect.width) * 100;

      if (dragState.isResize) {
        var newWidth = Math.max(0.8, dragState.startWidthPct + deltaPct);
        dragState.bar.style.width = newWidth + '%';
      } else {
        var newLeft = Math.max(0, Math.min(100 - dragState.startWidthPct, dragState.startLeftPct + deltaPct));
        dragState.bar.style.left = newLeft + '%';
      }
    });

    board.addEventListener('pointerup', function (e) {
      if (!dragState) return;

      dragState.bar.classList.remove('is-dragging');

      if (dragState.taskId && dragState.windowInfo) {
        var wi = dragState.windowInfo;
        var newLeftPct = parseFloat(dragState.bar.style.left) || 0;
        var newWidthPct = parseFloat(dragState.bar.style.width) || 1;

        var totalMs = wi.end - wi.start;
        var newStartMs = wi.start + (newLeftPct / 100) * totalMs;
        var newDurationMs = (newWidthPct / 100) * totalMs;
        var newEndMs = newStartMs + newDurationMs;

        var newStart = new Date(newStartMs);
        var newEnd = new Date(newEndMs);

        // Update via API
        var updateData = {
          start_at: newStart.toISOString().slice(0, 19).replace('T', ' '),
          due_at: newEnd.toISOString().slice(0, 19).replace('T', ' ')
        };

        tryRequest('PUT', 'api/v1/tasks/' + dragState.taskId, updateData)
          .then(function (result) {
            if (result && result.success !== false) {
              if (typeof notify === 'function') notify('Даты задачи обновлены', 'success');
            } else {
              if (typeof notify === 'function') notify('Ошибка сохранения дат', 'error');
            }
          })
          .catch(function () {
            if (typeof notify === 'function') notify('Ошибка сети', 'error');
          });
      }

      dragState = null;
    });
  }

  // 6. Export to PNG
  function crmGanttBindExport() {
    var btn = document.getElementById('ganttExportBtn');
    if (!btn || btn.dataset.exportBound === '1') return;
    btn.dataset.exportBound = '1';

    btn.addEventListener('click', function () {
      var board = document.querySelector('.crm-gantt-board');
      if (!board) return;

      if (typeof notify === 'function') {
        notify('Подготовка экспорта...', 'info');
      }

      // Use html2canvas if available, otherwise fallback to simple approach
      if (typeof html2canvas !== 'undefined') {
        html2canvas(board, {
          backgroundColor: '#ffffff',
          scale: 2,
          useCORS: true,
          logging: false
        }).then(function (canvas) {
          var link = document.createElement('a');
          link.download = 'gantt-' + new Date().toISOString().slice(0, 10) + '.png';
          link.href = canvas.toDataURL('image/png');
          link.click();
          if (typeof notify === 'function') notify('Диаграмма экспортирована', 'success');
        }).catch(function (err) {
          console.error('[GANTT] Export failed', err);
          if (typeof notify === 'function') notify('Ошибка экспорта', 'error');
        });
      } else {
        // Fallback: open print dialog
        window.print();
      }
    });
  }

  // Make items draggable
  function crmGanttMakeBarsDraggable() {
    document.querySelectorAll('.crm-gantt-bar:not(.crm-gantt-bar--project)').forEach(function (bar) {
      bar.classList.add('is-draggable');
    });
  }


  async function renderKanbanPage() {
    var tasksEnvelope = await tryRequest('api/v1/tasks', { query: { limit: 100 } });
    if (tasksEnvelope && tasksEnvelope.success !== false) {
      var tasks = mapItems(tasksEnvelope);
      window.CRM.kanbanTasks = tasks;
    }
    // Try to load configured statuses (order) from API; fall back to sensible defaults
    var statusOrder = ['new', 'in_progress', 'done'];
    try {
      // fetch global statuses in admin order, then pick those with scope 'task'
      var statusesEnvelope = await tryRequest('api/v1/statuses', { query: { limit: 200 } });
      if (statusesEnvelope && statusesEnvelope.success !== false) {
        var allStatuses = mapItems(statusesEnvelope).map(function (s) {
          return { code: String(s.code || ''), title: String(s.title || s.code || ''), sort_order: Number(s.sort_order || 0), scope: String(s.scope || '') };
        }).filter(function (s) { return s.code !== ''; }).sort(function (a, b) { return a.sort_order - b.sort_order; });
        var taskStatuses = allStatuses.filter(function (s) { return s.scope === 'task'; });
        if (taskStatuses.length > 0) {
          statusOrder = taskStatuses.map(function (s) { return s.code; });
          window.CRM.kanbanStatusMap = window.CRM.kanbanStatusMap || {};
          taskStatuses.forEach(function (s) { window.CRM.kanbanStatusMap[s.code] = s.title; });
        }
      }
    } catch (e) {
      // ignore and use fallback
    }
    window.CRM.kanbanStatusOrder = statusOrder;
    if (!window.CRM.kanbanMobileStatus || statusOrder.indexOf(window.CRM.kanbanMobileStatus) === -1) {
      window.CRM.kanbanMobileStatus = statusOrder[0] || 'new';
    }
    updateKanbanColumns();
    initKanbanSortable();
  }
  

  function saveKanbanOrder(statusCode, container) {
    var cards = container.querySelectorAll('.crm-kanban-card');
    var order = Array.from(cards).map(function (card) {
      var link = card.querySelector('a');
      return link ? link.href.split('task_public_id=')[1] : '';
    }).filter(Boolean).join('%2C');
    document.cookie = 'crm_kanban_order_' + statusCode + '=' + order + '; path=/; max-age=2592000'; // 30 days
  }

  function initKanbanSortable() {
    if (typeof Sortable === 'undefined') return;

    var columns = document.querySelectorAll('.crm-kanban-col');

    columns.forEach(function (col) {
      var statusCode = col.getAttribute('data-status-code') || 'new';
      var article = col.querySelector('article');
      if (!article) return;

      // destroy previous Sortable instance if exists
      try {
        var existing = Sortable.get(article);
        if (existing && existing.destroy) existing.destroy();
      } catch (e) {
        // ignore
      }

      Sortable.create(article, {
        // only allow dragging actual cards, not the article or columns
        draggable: '.crm-kanban-card',
        onMove: function (evt, originalEvent) {
          var dragged = evt.dragged || evt.dragged;
          if (!dragged) return false;
          return dragged.classList && dragged.classList.contains('crm-kanban-card');
        },
        group: 'kanban-cards',
        animation: 150,
        ghostClass: 'crm-kanban-card-ghost',
        chosenClass: 'crm-kanban-card-chosen',
        dragClass: 'crm-kanban-card-drag',
        onEnd: function (evt) {
          var item = evt.item;
          var fromCol = evt.from.closest('.crm-kanban-col');
          var toCol = evt.to.closest('.crm-kanban-col');
          var fromStatus = (fromCol && fromCol.getAttribute('data-status-code')) || 'new';
          var toStatus = (toCol && toCol.getAttribute('data-status-code')) || 'new';

          if (fromStatus !== toStatus) {
            // Update status via API
            var taskLink = item.querySelector('a');
            if (taskLink) {
              var href = taskLink.href;
              var publicId = href.split('task_public_id=')[1];
              var rowVersion = item.getAttribute('data-row-version') || '';
              if (publicId) {
                tryRequest('api/v1/tasks/' + publicId, {
                  method: 'PATCH',
                  body: { status: toStatus, row_version: rowVersion }
                }).then(function (response) {
                    if (response && response.success) {
                      notify('Статус задачи обновлен');
                      // Update task status locally and row_version if provided
                      var task = window.CRM.kanbanTasks.find(function (t) { return t.public_id === publicId; });
                      var newRowVersion = '';
                      if (response.meta && response.meta.row_version) {
                        newRowVersion = response.meta.row_version;
                      } else if (response.data && response.data.task && response.data.task.row_version) {
                        newRowVersion = response.data.task.row_version;
                      } else if (response.data && response.data.row_version) {
                        newRowVersion = response.data.row_version;
                      }
                      if (task) {
                        task.status_code = toStatus;
                        if (newRowVersion) task.row_version = newRowVersion;
                      }
                      // Update DOM item row_version immediately if available
                      if (newRowVersion && item && item.setAttribute) {
                        item.setAttribute('data-row-version', String(newRowVersion));
                      }
                      updateKanbanColumns();
                      // Re-init sortable bindings for newly rendered columns
                      initKanbanSortable();
                    } else {
                    console.log('Update status response errors:', response.errors);
                    if (response.errors && response.errors.status && response.errors.status[0]) {
                      console.log('Status error:', response.errors.status[0]);
                    }
                    notify('Ошибка обновления статуса', 'error');
                    // Revert
                    evt.from.appendChild(item);
                  }
                }).catch(function (error) {
                  console.log('Update status network error:', error);
                  notify('Ошибка обновления статуса', 'error');
                  // Revert
                  evt.from.appendChild(item);
                });
              }
            }
          }

          // Save order in cookie
          saveKanbanOrder(toStatus, evt.to);
          if (fromStatus !== toStatus) {
            saveKanbanOrder(fromStatus, evt.from);
          }
        }
      });
    });
  }

  function updateKanbanColumns() {
    var tasks = window.CRM.kanbanTasks || [];
    console.log('updateKanbanColumns, tasks length:', tasks.length);
    var byStatus = {};
    tasks.forEach(function (task) {
      var status = task.status_code || 'new';
      if (!byStatus[status]) byStatus[status] = [];
      byStatus[status].push(task);
    });
    console.log('byStatus:', byStatus);

    var statusOrder = window.CRM.kanbanStatusOrder || ['new', 'todo', 'in_progress', 'done'];
    var statusMap = window.CRM.kanbanStatusMap || {};
    var container = document.querySelector('.crm-kanban');
    var mobileTabs = document.getElementById('kanbanMobileStatusTabs');
    if (!container) return;

    // Build final status list.
    // Preserve the first computed order across re-renders to avoid columns jumping around.
    if (!window.CRM.kanbanFinalOrder || !Array.isArray(window.CRM.kanbanFinalOrder)) {
      var extraStatuses = Object.keys(byStatus).filter(function (s) { return statusOrder.indexOf(s) === -1; });
      // keep deterministic order for extras (alphabetical) on first render
      extraStatuses.sort();
      window.CRM.kanbanFinalOrder = statusOrder.concat(extraStatuses);
    } else {
      // ensure any newly appeared statuses are appended at the end, preserving previous order
      var existing = window.CRM.kanbanFinalOrder.slice();
      Object.keys(byStatus).forEach(function (s) {
        if (existing.indexOf(s) === -1) existing.push(s);
      });
      window.CRM.kanbanFinalOrder = existing;
    }
    var finalOrder = window.CRM.kanbanFinalOrder;
    var isMobile = window.matchMedia && window.matchMedia('(max-width: 767.98px)').matches;
    var activeMobileStatus = String(window.CRM.kanbanMobileStatus || '').trim();
    if (isMobile && finalOrder.indexOf(activeMobileStatus) === -1) {
      activeMobileStatus = finalOrder[0] || 'new';
      window.CRM.kanbanMobileStatus = activeMobileStatus;
    }

    // Hardcoded fallbacks for titles
    var hardcodedTitles = {
      'new': 'Новая',
      'todo': 'К выполнению',
      'in_progress': 'В работе',
      'done': 'Завершена',
      'blocked': 'Заблокирована',
      'review': 'Ревью',
      'qa_testing': 'QA тестирование',
      'ready_release': 'Готова к релизу'
    };

    // Rebuild columns to avoid duplicates and support dynamic statuses
    container.innerHTML = '';
    finalOrder.forEach(function (statusCode) {
      if (isMobile && statusCode !== activeMobileStatus) return;
      var title = statusMap[statusCode] || hardcodedTitles[statusCode] || statusCode;
      var section = document.createElement('section');
      section.className = 'crm-kanban-col';
      // expose status code for each column so Sortable handlers can read exact code
      section.setAttribute('data-status-code', statusCode);

      var header = document.createElement('div');
      header.className = 'd-flex justify-content-between mb-2';
      var strong = document.createElement('strong');
      strong.textContent = title;
      var chip = document.createElement('span');
      chip.className = 'crm-chip';
      chip.textContent = '0';
      header.appendChild(strong);
      header.appendChild(chip);

      var article = document.createElement('article');
      article.className = 'text-muted';
      article.textContent = 'Загрузка задач...';

      section.appendChild(header);
      section.appendChild(article);
      container.appendChild(section);
    });

    if (mobileTabs) {
      if (!isMobile) {
        mobileTabs.innerHTML = '';
      } else {
        mobileTabs.innerHTML = finalOrder.map(function (statusCode) {
          var title = statusMap[statusCode] || hardcodedTitles[statusCode] || statusCode;
          var count = (byStatus[statusCode] || []).length;
          var activeClass = statusCode === activeMobileStatus ? ' is-active' : '';
          return '<button type="button" class="btn crm-btn-secondary' + activeClass + '" data-kanban-mobile-status="' + safeText(statusCode) + '">' + safeText(title) + ' (' + safeText(String(count)) + ')</button>';
        }).join('');
        Array.prototype.slice.call(mobileTabs.querySelectorAll('[data-kanban-mobile-status]')).forEach(function (btn) {
          if (btn.dataset.bound === '1') return;
          btn.dataset.bound = '1';
          btn.addEventListener('click', function () {
            var next = String(btn.getAttribute('data-kanban-mobile-status') || '').trim();
            if (!next || window.CRM.kanbanMobileStatus === next) return;
            window.CRM.kanbanMobileStatus = next;
            updateKanbanColumns();
            initKanbanSortable();
          });
        });
      }
    }

    // Populate columns
    var columns = container.querySelectorAll('.crm-kanban-col');
    columns.forEach(function (col, index) {
      var statusCode = finalOrder[index] || 'new';
      var statusTasks = byStatus[statusCode] || [];

      // Sort by cookie
      var cookieName = 'crm_kanban_order_' + statusCode;
      var savedOrder = (document.cookie.split('; ').find(function (row) { return row.startsWith(cookieName + '='); }) || '').split('=')[1];
      if (savedOrder) {
        var order = savedOrder.split('%2C').filter(Boolean);
        statusTasks.sort(function (a, b) {
          var aIndex = order.indexOf(a.public_id);
          var bIndex = order.indexOf(b.public_id);
          if (aIndex === -1) aIndex = 999;
          if (bIndex === -1) bIndex = 999;
          return aIndex - bIndex;
        });
      }

      var countSpan = col.querySelector('.crm-chip');
      if (countSpan) countSpan.textContent = statusTasks.length;

      var article = col.querySelector('article');
      if (article) {
          if (statusTasks.length > 0) {
          article.innerHTML = statusTasks.map(function (task) {
            return '<div class="crm-kanban-card" data-public-id="' + safeText(task.public_id) + '" data-row-version="' + safeText(task.row_version || '') + '"><h6><a href="' + taskLink(task.public_id) + '">' + safeText(task.title) + '</a></h6><p>' + safeText(task.description || '') + '</p></div>';
          }).join('');
        } else {
          article.innerHTML = '<div class="crm-kanban-card text-muted">Нет задач</div>';
        }
      }
    });
  }
